return ['project-id-version' => '#1 RW Wordpress Addon', 'report-msgid-bugs-to' => 'https://wordpress.org/support/plugin/wp-addon-plugin', 'pot-creation-date' => '2026-09-17T10:36:17+00:00', 'po-revision-date' => '2026-11-16 07:49+0000', 'last-translator' => 'Алексей Тихомиров', 'language-team' => 'Русский', 'language' => 'ru_RU', 'mime-version' => '1.0', 'content-type' => 'text/plain; charset=UTF-8', 'content-transfer-encoding' => '8bit', 'plural-forms' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);', 'x-generator' => 'Loco https://localise.biz/', 'x-loco-version' => '2.8.8; wp-7.2-alpha-64027; php-8.3.36', 'messages' => [' Errors: %d.' => 'Ошибки: %d.', '![alt](url) — image' => '![alt](url) — изображение', '# Heading 1 — large heading' => '# Заголовок 1 — крупный заголовок', '# WP Excellence Addon' => '# WP Excellence Addon', '## Heading 2 — medium heading' => '## Заголовок 2 — средний заголовок', '* item — bullet list' => '* пункт — маркированный список', '**bold** — bold text' => '**жирный** — жирный текст', '*italic* — italic text' => '*курсив* — курсивный текст', '/page and /page/ are treated the same. You can write either form — the plugin compares paths without a trailing slash.' => 'Пути /page и /page/ обрабатываются одинаково. Вы можете использовать любой из этих вариантов — плагин сравнивает пути без завершающей косой черты.', '1. item — numbered list' => '1. Пункт — нумерованный список', '301 redirect management for old URLs, moved pages and bulk migrations. Read the guide below for slash rules, wildcard examples and CSV import format.' => 'Управление редиректами 301 для старых URL, перенесённых страниц и массовых миграций. Ниже — инструкция: слеши, примеры с * и формат CSV.', '[text](url) — link' => '[текст](url) — ссылка', '`code` — inline code' => '`code` — встроенный код', 'A comment is blocked when the sum of the heuristic weights reaches this value. Higher is safer for real readers, lower catches more bots. <strong>3</strong> is the recommended balance.' => 'Комментарий блокируется, когда сумма эвристических весов достигает этого значения. Чем выше значение, тем безопаснее для реальных читателей, чем ниже, тем больше ботов будет обнаружено. Рекомендуемое значение — <strong>3</strong>.', 'Access denied.' => 'Доступ запрещен.', 'Actions' => 'Действия', 'Activate' => 'Активировать', 'Add a pack color to tinyMCE' => 'Добавьте пак цветов в tinyMCE', 'Add all types at a glance widget' => 'Добавить все типы в виджет "glance"', 'Add Banner Image' => 'Добавить изображение баннера', 'Add search filter for taxonomy checklists in post editor' => 'Добавьте фильтр поиска для контрольных списков таксономии в редакторе записей.', 'Add table plugin' => 'Добавить плагин таблиц', 'Add TinyMCE Advanced functions' => 'Добавить расширенные функции TinyMCE', 'Add VK and OK to user profile' => 'Добавить ВК и ОК в профиль пользователя', 'Additional shortcodes <b>email:</b>' => 'Дополнительные шорткоды <b>email:</b>', 'Additional sidebar 1' => 'Дополнительная боковая панель 1', 'Additional sidebar 2' => 'Дополнительная боковая панель 2', 'Additional sidebar 3' => 'Дополнительная боковая панель 3', 'Adds a Duplicate action for posts and pages. Creates a draft copy with the same content.' => 'Добавляет действие «Дублировать» для записей и страниц. Создаёт черновик-копию с тем же содержимым.', 'Adds a hidden field to the comment form. Browsers and password managers fill nothing there, static bots fill everything. JavaScript removes the field before submit, so a filled field means a bot.' => 'Добавляет скрытое поле в форму комментариев. Браузеры и менеджеры паролей ничего в него не заполняют, статические боты заполняют всё. JavaScript удаляет поле перед отправкой, поэтому заполненное поле означает, что его заполнил бот.', 'Adds a list of installed plugins with versions to the dashboard. Visible to administrators only.' => 'Добавляет на рабочий стол список установленных плагинов с версиями. Видентолько администраторам.', 'Adds a search field to hierarchical taxonomy checklists in the classic post editor. Does not affect Gutenberg panels or non-hierarchical tag inputs.' => 'Добавляет поиск по спискам иерархических таксономий в классическом редакторе. Не влияет на панели Gutenberg и поля ввода обычных меток.', 'Adds a second toolbar: fonts, sizes, tables, subscript/superscript, and extra formatting buttons.' => 'Добавляет вторую панель инструментов: шрифты, размеры, таблицы,подстрочные/надстрочные символы и дополнительные кнопки форматирования.', 'Adds a WordPress roles list widget to the dashboard. Helps you recall role slugs when configuring permissions.' => 'Добавляет виджет со списком ролей WordPress на рабочем столе. Помогаетбыстро вспомнить slug роли при настройке прав.', 'Adds an extended text and background color palette in the visual editor.' => 'Добавляет расширенную палитру цветов текста и фона в визуальном редакторе.', 'Adds an ID column to post, page, and media lists. Handy for shortcodes, SQL queries, and debugging.' => 'Добавляет колонку ID в списки записей, страниц и медиафайлов. Удобно дляшорткодов, SQL-запросов и отладки.', 'Adds legacy WebP MIME and preview compatibility filters. Modern WordPress supports WebP natively; disabling this option does not disable WebP support.' => 'Добавляет устаревшие фильтры совместимости MIME и предпросмотра WebP. Современный WordPress поддерживает WebP без них; отключение настройки не отключает WebP.', 'Adds meta robots noindex on every page of the site. Use on test or staging hosts so search engines do not index a draft site. Different from Tweaks "Noindex for search, attachment and date archives", which only targets low-value archive pages.' => 'Добавляет meta robots noindex на все страницы сайта. Используйте на тестовомили staging-хосте, чтобы поисковики не индексировали черновой сайт.Отличается от твика «Noindex for search, attachment and date archives»,который закрывает только архивы.', 'Adds noindex for search results, attachment pages, and date archives. These pages are rarely useful in Google and often create duplicates. Different from General Settings → Disable site indexing, which blocks the entire site.' => 'Добавляет noindex для страниц поиска, вложений и архивов по датам. Этистраницы редко полезны в поиске Google и часто создают дубли. Отличается отGeneral Settings → Disable site indexing, который закрывает весь сайт.', 'Adds VK and Odnoklassniki fields to the user profile and removes outdated AIM/Jabber/Yahoo IM fields.' => 'Добавляет поля VK и Odnoklassniki в профиль пользователя и убираетустаревшие AIM/Jabber/Yahoo IM.', 'Admin dashboard widgets' => 'Виджеты панели администратора', 'Administrators and editors never pass through the checks, so a real person replying from the admin panel cannot be blocked.' => 'Администраторы и редакторы никогда не проходят эти проверки, поэтому реального человека, отвечающего из административной панели, невозможно заблокировать.', 'Ads in content' => 'Реклама в контенте', 'Ads manager' => 'Менеджер рекламы', 'ADs Mode' => 'Режим рекламы', 'Advanced Advertising mode. For developers.' => 'Режим расширенной рекламы. Для разработчиков.', 'After content' => 'После контента', 'Aleksey Tikhomirov' => 'Aleksey Tikhomirov', 'All categories' => 'Все категории', 'All revision' => 'Все ревизии', 'All revisions were removed from posts and related rows in term_relationships, postmeta, and comments.' => 'Все ревизии удалены из posts и связанных строк в term_relationships, postmeta и comments.', 'Allow shortcode in "Text" widget' => 'Разрешить шорткод в виджете «Текст»', 'Allow SVG support for media' => 'Разрешить поддержку SVG для мультимедиа', 'Allow WEBP support for media' => 'Разрешить поддержку WEBP для мультимедиа', 'Allows shortcodes to run in text and block widgets. Needed if you insert [shortcode] directly into a widget.' => 'Разрешает выполнение шорткодов в текстовых и блочных виджетах. Нужно, есливы вставляете [shortcode] прямо в виджет.', 'Allows uploading additional file types: SVG, DOC, WebP, and others. SVG is handy for icons but may contain malicious code — upload only trusted files. Also adds WebP and SVG MIME types; use settings 34 and 35 below for media library preview support.' => 'Разрешает загрузку дополнительных типов файлов: SVG, DOC, WebP и др. SVGудобны для иконок, но могут содержать вредоносный код — загружайте толькопроверенные файлы. Также добавляет MIME-типы WebP и SVG; для предпросмотра вмедиабиблиотеке используйте настройки 34 и 35 ниже.', 'Analytics code' => 'Аналитический код', 'Any HTML code in footer.' => 'Любой HTML-код в футере.', 'Any HTML code or Analytics code in header.' => 'Любой HTML-код или код Analytics в header.', 'Any widgets' => 'Любые виджеты', 'Are you sure you want to uninstall this plugin?' => 'Вы уверены, что хотите удалить этот плагин?', 'Are you sure? This action cannot be undone.' => 'Вы уверены? Это действие нельзя отменить.', 'Args' => 'Аргументы', 'Asset Minification' => 'Минификация Assets', 'Asset optimization is a comprehensive system for improving site performance by minifying and combining CSS/JavaScript files. The module automatically analyzes all connected resources and applies optimal optimization strategies.<br><br><strong>Benefits:</strong><br>• Reduce file size by 20-40%<br>• Decrease number of HTTP requests<br>• Speed up page loading<br>• Better PageSpeed Insights scores<br><br><strong>Automatic logic:</strong><br>• Excludes WordPress system resources<br>• Does not process files smaller than 1KB<br>• Skips already minified files<br>• Analyzes resource loading priorities' => 'Оптимизация ресурсов — это комплексная система для повышения производительности сайта путём минификации и объединения CSS/JavaScript-файлов. Модуль автоматически анализирует все подключенные ресурсы и применяет оптимальные стратегии оптимизации.<br><br><strong>Преимущества:</strong><br>• Уменьшение размера файла на 20–40%<br>• Уменьшение количества HTTP-запросов<br>• Ускорение загрузки страниц<br>• Улучшение показателей PageSpeed Insights<br><br><strong>Автоматическая логика:</strong><br>• Исключение системных ресурсов WordPress<br>• Не обрабатывает файлы размером менее 1 КБ<br>• Пропускает уже минифицированные файлы<br>• Анализ приоритетов загрузки ресурсов', 'Author' => 'Автор', 'Automatically empties the WordPress trash after 14 days. Helps keep deleted posts and comments from bloating the database.' => 'Автоматически очищает корзину WordPress через 14 дней. Помогает не раздуватьбазу удалёнными записями и комментариями.', 'Automatically extracts and embeds inline critical CSS styles (header, menu, main content) for instant display of above-the-fold content. Improves First Contentful Paint score in Lighthouse.' => 'Автоматически извлекает и встраивает критически важные встроенные стили CSS (заголовок, меню, основной контент) для мгновенного отображения контента в верхней части страницы. Улучшает показатель First Contentful Paint в Lighthouse.', 'AutoRemove readme.html and license.txt files' => 'Автоудаление readme.html and license.txt файлов', 'Backup created: %1$d tables, %2$s.' => 'Создана резервная копия: таблиц %1$d, %2$s.', 'Backup DB' => 'Резервное копирование базы данных', 'Backup file deleted.' => 'Резервная копия удалена.', 'Backup file not found.' => 'Резервная копия файла не найдена.', 'Backup files' => 'Резервные файлы', 'Backup Settings' => 'Бэкап', 'Backup uploaded.' => 'Резервная копия загружена.', 'Banner code' => 'Код баннера', 'Banner html code' => 'HTML-код баннера', 'Banner position' => 'Позиция баннера', 'Banner text' => 'Текст баннера', 'Before content' => 'До контента', 'Block WordPress and Automattic tracking pixel' => 'Блокировка пикселя отслеживания WordPress и Automattic', 'Blocked in 30 days: %s' => 'Заблокировано через 30 дней: %s', 'Blocks background requests to api.wordpress.org and downloads.wordpress.org. Useful on closed servers, but WordPress will stop checking core, plugin, and theme updates. Skipped automatically when General Settings → Disable all updates is enabled.' => 'Блокирует фоновые запросы к api.wordpress.org и downloads.wordpress.org.Полезно на закрытых серверах, но WordPress перестанет сам проверятьобновления. Автоматически не применяется, если в General Settings включено«Disable all updates».', 'Blocks requests to pixel.wp.com, stats.wp.com, and WordPress Events in the admin. Also disables WooCommerce/Jetpack tracking when those plugins are installed. Does not block core updates.' => 'Блокирует отправку статистики на pixel.wp.com, stats.wp.com и запросыWordPress Events в админке. Также отключает трекинг WooCommerce/Jetpack,если эти плагины установлены. Не мешает обновлениям ядра.', 'Blur effect intensity' => 'Интенсивность эффекта размытия', 'Bootstrap 3 (recommended)' => 'Bootstrap 3 (рекомендуется)', 'Bootstrap 3 is the supported framework for the current theme and shortcodes. Bootstrap 5 and Tailwind are reserved for future use and may not match the frontend styles yet.' => 'Bootstrap 3 — поддерживаемый фреймворк для текущей темы и шорткодов. Bootstrap 5 и Tailwind зарезервированы на будущее и могут не совпадать со стилями фронтенда.', 'Bootstrap 5 (future)' => 'Bootstrap 5 (в будущем)', 'Bottom center' => 'Нижний центр', 'Bottom left' => 'Внизу слева', 'Bottom right' => 'Внизу справа', 'Bulk CSV import' => 'Массовый импорт (CSV)', 'Bulk GUID replacement' => 'Массовая замена GUID', 'Button 1 text' => 'Текст кнопки 1', 'Button 2 text' => 'Текст кнопки 2', 'Buttons mode' => 'Режим кнопок', 'by Aleksey Tihomirov' => 'от Алексей Тихомиров', 'By reason' => 'По причине', 'Cache' => 'Кэш', 'Cache lifetime (seconds)' => 'Время жизни кэша (секунды)', 'Categories to hide on the frontend' => 'Категории, скрываемые на фронтенде', 'Category' => 'Категория', 'Change length post excerpt? To maximum 200 symbols.' => 'Изменить длину отрывка из поста? Максимум до 200 символов.', 'Change login error message' => 'Изменить сообщение об ошибке при входе в систему', 'Change to On for enable this.' => 'Измените значение на «Вкл.», чтобы включить это.', 'Choose a backup file.' => 'Выберите файл резервной копии.', 'Choose an image' => 'Выберите изображение', 'Choose file' => 'Выбрать файл', 'Classic editor' => 'Классический редактор', 'Clean up unused image sizes' => 'Очистите неиспользуемые размеры изображений', 'Clear cache on post publish' => 'Очистить кэш при публикации поста', 'Clone' => 'клонировать', 'Clone this Widget' => 'Клонирование виджетов', 'Closes the REST API for guests. Improves security but may break some forms, frontend Gutenberg blocks, and integrations. Enable only after testing.' => 'Закрывает REST API для гостей. Повышает безопасность, но может сломатьнекоторые формы, блоки Gutenberg на фронте и интеграции. Включайте послепроверки.', 'CodeStar Framework installed. Reload the page to open the settings.' => 'Установлен фреймворк CodeStar. Перезагрузите страницу, чтобы открыть настройки.', 'Collects all suitable CSS files into one combined file, reducing the number of HTTP requests to the server. Automatically excludes WordPress system styles. Effective for sites with 3+ CSS files.' => 'Собирает все подходящие CSS-файлы в один общий файл, сокращая количество HTTP-запросов к серверу. Автоматически исключает системные стили WordPress. Эффективно для сайтов с тремя и более CSS-файлами.', 'Combine CSS files' => 'Объединить CSS-файлы', 'Combine JavaScript files' => 'Объединить файлы JavaScript', 'Combines JS files into one loaded in the footer. Reduces the number of requests, but may break loading order. Recommended to test for JavaScript errors after enabling.' => 'Объединяет JS-файлы в один, загружаемый в нижний колонтитул. Уменьшает количество запросов, но может нарушить порядок загрузки. Рекомендуется проверить наличие ошибок JavaScript после включения.', 'Comment' => 'Комментарий', 'Comment form' => 'Форма комментариев', 'Comment Spam' => 'Спам в комментариях', 'Comment spam protection. A rejected comment never reaches the database, so nothing is stored, no notification email is sent, and the page cache stays intact.<br><br><strong>How it works:</strong> a hidden honeypot field, a time trap that only a real browser can pass, pingback and trackback backlink verification, and content scoring. The weight count includes links in the body, an author name repeating a linked domain, spam niche vocabulary and bulk-registered domains; when the score reaches the threshold the submission is rejected, and between the moderation hold score and the threshold the comment goes to the moderation queue instead. Every blocked or held attempt is logged with its IP and reason and rotated out monthly.<br><br>This module replaces the <strong>Kama SpamBlock</strong> plugin, which can be deactivated afterwards.' => 'Защита от спама в комментариях. Отклоненный комментарий никогда не попадает в базу данных, поэтому ничего не сохраняется, уведомление по электронной почте не отправляется, и кэш страницы остается нетронутым.<br><br><strong>Как это работает:</strong> скрытое поле-ловушка, временная ловушка, которую может преодолеть только настоящий браузер, проверка обратных ссылок (pingback и trackback) и оценка контента. Весовой коэффициент включает ссылки в теле комментария, имя автора, повторяющее связанный домен, нишевую лексику спама и домены, зарегистрированные массово; когда оценка достигает порогового значения, отправка отклоняется, а в промежутке между оценкой модерации и пороговым значением комментарий отправляется в очередь модерации. Каждая заблокированная или отложенная попытка регистрируется с указанием IP-адреса и причины и ежемесячно удаляется.<br><br>Этот модуль заменяет плагин <strong>Kama SpamBlock</strong>, который можно деактивировать впоследствии.', 'Comments scoring this value or more but staying below the scoring threshold are held for moderation instead of being approved: borderline comments cannot publish themselves. Set to 0 to disable holding.' => 'Комментарии, набравшие это значение или больше, но остающиеся ниже порогового значения, отправляются на модерацию вместо утверждения: комментарии, находящиеся на грани, не могут быть опубликованы. Установите значение 0, чтобы отключить отправку на модерацию.', 'Components' => 'Компоненты', 'Compresses JS code by removing comments, extra spaces and formatting. Skips minified files and files smaller than 1KB. Important: check functionality after enabling, as some plugins may have minification-sensitive code.' => 'Сжимает JS-код, удаляя комментарии, лишние пробелы и форматирование. Пропускает минифицированные файлы и файлы размером менее 1 КБ. Важно: проверьте работоспособность после включения, так как некоторые плагины могут содержать код, чувствительный к минификации.', 'Contact Form 7 settings' => 'CF7 настройки', 'Content conversion error' => 'Ошибка преобразования контента', 'Convert HTML from the classic editor to Markdown' => 'Преобразуйте HTML-код из классического редактора в Markdown.', 'Convert Markdown to HTML for the classic editor' => 'Преобразуйте Markdown в HTML для классического редактора.', 'Convert Markdown to HTML for the classic editor?' => 'Как преобразовать Markdown в HTML для классического редактора?', 'Cookie Banner' => 'Баннер с печеньем', 'Cookie consent' => 'Согласие на использование файлов cookie', 'Cookie consent banner with configurable text, links, button mode and deferred analytics loading.' => 'Баннер согласия на использование файлов cookie с настраиваемым текстом, ссылками, режимом кнопки и отложенной загрузкой аналитики.', 'Could not activate plugin: %s' => 'Не удалось активировать плагин: %s', 'Could not connect to the filesystem to install CodeStar Framework.' => 'Не удалось подключиться к файловой системе для установки CodeStar Framework.', 'Could not create the backup directory.' => 'Не удалось создать каталог резервных копий.', 'Could not create the directory %s for the CodeStar Framework.' => 'Не удалось создать каталог %s для фреймворка CodeStar.', 'Could not delete the backup file.' => 'Не удалось удалить файл резервной копии.', 'Could not delete the file.' => 'Не удалось удалить файл.', 'Could not load the plugin list.' => 'Не удалось загрузить список плагинов.', 'Could not load the plugin list:' => 'Не удалось загрузить список плагинов:', 'Could not move the CodeStar Framework into the plugin directory.' => 'Не удалось переместить CodeStar Framework в каталог плагинов.', 'Could not rename plugin folder.' => 'Не удалось переименовать папку плагина.', 'Could not save the uploaded backup.' => 'Не удалось сохранить загруженную резервную копию.', 'Create backup' => 'Создать резервную копию', 'Created' => 'Созданный', 'CSS Code in Header' => 'CSS-код в Header', 'CSS framework for TinyMCE preview' => 'CSS-фреймворк для предпросмотра TinyMCE', 'Custom code' => 'Свой код', 'Custom Default Avatar' => 'Аватар по умолчанию', 'Custom text shown on the maintenance page. Leave empty to use the default message.' => 'Пользовательский текст на странице техработ. Оставьте пустым, чтобы использовать сообщение по умолчанию.', 'Daily sliding window limit per IP address. Disabled by default. Set to 0 to keep it off.' => 'Ежедневное ограничение на использование скользящего окна для каждого IP-адреса. По умолчанию отключено. Установите значение 0, чтобы отключить эту функцию.', 'Data Base Optimization' => 'Оптимизая БД', 'Database restored: %1$d tables, %2$s rows.' => 'База данных восстановлена: %1$d таблиц, %2$s строк.', 'Deactivate' => 'Деактивировать', 'Deactivate Kama SpamBlock' => 'Отключить Kama SpamBlock', 'Default to Markdown editor' => 'По умолчанию используется редактор Markdown.', 'Defer non-critical CSS' => 'Отложить некритический CSS', 'Degree of blur placeholder blur. Value 1 - weak blur, 10 - strong. Recommended 3-7 for optimal quality and performance balance.' => 'Степень размытия. Значение 1 — слабое размытие, 10 — сильное. Рекомендуется 3–7 для оптимального баланса качества и производительности.', 'Delete' => 'Удалить', 'Delete all revisions and related rows.' => 'Удалить все ревизии и связанные записи.', 'Delete backup file?' => 'Удалить резервную копию файла?', 'Deleted %d files.' => 'Удалено %d файлов.', 'Deletes readme.html and license.txt from the site root when an administrator opens the admin. These files can reveal the WordPress version to outsiders.' => 'Удаляет readme.html и license.txt из корня сайта при заходе администратора вадминку. Эти файлы могут подсказать версию WordPress посторонним.', 'Disable application passwords' => 'Отключить пароли приложений', 'Disable browser checking in dashboard' => 'Отключить проверку браузера в панели управления', 'Disable comments' => 'Отключить комментарии', 'Disable dashicons CSS for guests' => 'Отключить CSS-стили для дашиконов для гостей', 'Disable guttenberg for widgets' => 'Отключить Гуттенберг для виджетов', 'Disable link Nofollow in comment' => 'Отключить ссылку Nofollow в комментарии', 'Disable new themes on major WP updates' => 'Отключайте новые темы в основных обновлениях WP', 'Disable pingback from this site to this site' => 'Отключить pingbackи сайта', 'Disable theme and plugin file editor in admin' => 'Отключите редактор файлов тем и плагинов в админке.', 'Disable URL auto-linking in comments' => 'Отключить автоматическую привязку URL-адресов в комментариях', 'Disable wp-embed script on frontend' => 'Отключить скрипт wp-embed на внешнем интерфейсе.', 'Disable XML-RPC' => 'Отключить XML-RPC', 'Disables Application Passwords for REST API access. Rarely needed; if you do not use external apps with WP access, it is safer to keep this enabled.' => 'Отключает Application Passwords — пароли приложений для REST API. Нужныредко; если не используете внешние приложения с доступом к WP, лучшезакрыть.', 'Disables automatic update checks on every admin visit. Reduces load, but even administrators will not see update notices until they open Updates manually. Skipped automatically when General Settings → Disable all updates is enabled.' => 'Отключает автоматическую проверку обновлений при каждом заходе в админку.Снижает нагрузку, но даже администратор не увидит напоминания обобновлениях, пока не зайдёт в «Обновления» вручную. Автоматически неприменяется, если в General Settings включено «Disable all updates».', 'Disables comments on the site. If no post types are selected below, comments are disabled everywhere. If you select post types, comments stay enabled only where you need them.' => 'Отключает комментарии на сайте. Если ниже не выбраны типы записей —отключение будет для всех типов. Если выбрать типы — комментарии останутсятолько там, где они нужны.', 'Disables Heartbeat on the public site and slows it down in the admin. This reduces extra AJAX requests. Post autosave remains, but runs less often.' => 'Отключает Heartbeat на публичной части сайта и замедляет его в админке. Этоснижает лишние AJAX-запросы. В редакторе постов автосохранение остаётся, нореже.', 'Disables outdated browser checks in the WordPress dashboard. Removes an extra request to WordPress.org and annoying warnings.' => 'Отключает проверку устаревшего браузера в консоли WordPress. Убирает лишнийзапрос к WordPress.org и назойливые предупреждения.', 'Disables publishing posts by email. Almost nobody needs this feature, and it is better to close an unused entry point.' => 'Отключает публикацию записей по e-mail. Эта функция почти никому не нужна, алишний вход в систему лучше закрыть.', 'Disables the wp-embed.js script WordPress loads for post embeds. On a regular site it is rarely needed and saves a few kilobytes.' => 'Отключает скрипт wp-embed.js, который WordPress подключает для встраиваниязаписей. На обычном сайте он почти не нужен и экономит несколько килобайт.', 'Disables WordPress emoji scripts and styles. Pages load faster, especially if you do not use emoji in content.' => 'Отключает смайлики WordPress и лишние скрипты/стили для них. Страницыгрузятся быстрее, особенно если вы не используете emoji в контенте.', 'Disables XML-RPC — an old interface for remote publishing and some attacks. If you do not publish via external XML-RPC apps, it is safer to keep this enabled.' => 'Отключает XML-RPC — старый интерфейс для удалённой публикации и некоторыхатак. Если вы не публикуете посты через внешние приложения по XML-RPC, лучшедержать включённым.', 'Displays HTML content in the selected jQuery selector, anywhere on the site.' => 'Отображает HTML-контент в выбранном селекторе jQuery в любом месте сайта.', 'Displays HTML content in the selected location of the post' => 'Отображает HTML-контент в выбранном месте поста.', 'Distance from viewport edge at which to start loading. Example: 50px - loading 50px before element appears. 10% - 10% of viewport height.' => 'Расстояние от края области просмотра, с которого начинается загрузка. Пример: 50 пикселей — загрузка за 50 пикселей до появления элемента. 10% — 10% от высоты области просмотра.', 'Do not cache for logged-in users' => 'Не кэшировать для зарегистрированных пользователей', 'Do not cache these pages' => 'Не кэшируйте эти страницы', 'Does not load dashicons CSS for logged-out visitors. Saves about 30 KB if the frontend has no admin UI elements.' => 'Не загружает CSS-иконки dashicons для неавторизованных посетителей. Экономит~30 KB, если на фронте нет элементов админки.', 'Does not move selected categories and tags to the top of the list. Makes long category trees easier to scan.' => 'Не поднимает выбранные рубрики и метки наверх списка. Так прощеориентироваться в длинном дереве категорий.', 'Done.' => 'Сделано.', 'Download' => 'Скачать', 'Download backup' => 'Скачать резервную копию', 'Download settings now' => 'Скачать настройки', 'Elements' => 'Элементы', 'Empty WP-Trash every 14 days' => 'Очищать WP-корзину каждые 14 дней', 'Enable "Open Sans" google font for tinyMCE.' => 'Включить шрифт Google "Open Sans" для TinyMCE.', 'Enable asset optimization' => 'Включить оптимизацию активов', 'Enable comment spam protection' => 'Включить защиту от спама в комментариях', 'Enable cookie banner' => 'Включить баннер с уведомлением о файлах cookie', 'Enable CSS framework in editor' => 'Подключить CSS-фреймворк в редакторе', 'Enable duplicate post and page' => 'Включить дублирование поста и страницы', 'Enable Duplicate widgets' => 'Включить дублирование виджетов', 'Enable fallback for older browsers' => 'Включить откат для старых браузеров', 'Enable FAQ shortcode' => 'Включить шорткод FAQ', 'Enable hierarchical tags rewrite rules' => 'Включить правила перезаписи иерархических тегов', 'Enable jQuery ADs mode' => 'Включить режим jQuery AD', 'Enable lazy loading' => 'Включить ленивую загрузку', 'Enable Markdown editor' => 'Включить редактор Markdown', 'Enable Media Cleanup' => 'Включить очистку мультимедиа', 'Enable page caching' => 'Включить кэширование страниц', 'Enable redirects' => 'Включить перенаправления', 'Enable Table of Content shortcode' => 'Включить шорткод таблицы содержания', 'Enable this extension?' => 'Включить это расширение?', 'Enable transliteration?' => 'Включить транслитерацию?', 'Enables creating and editing tables in TinyMCE with ready-made Bootstrap CSS classes.' => 'Включает создание и редактирование таблиц прямо в TinyMCE, с готовыми CSS-классами Bootstrap.', 'Enables pretty URLs for nested tags such as /tag/git/submodules/. The rewrite rule maps to the final tag slug, not the full path. Permalinks are flushed automatically when this option changes.' => 'Включает красивые URL для вложенных тегов, например /tag/git/submodules/. Правило rewrite ведёт на конечный slug тега, а не на весь путь. Постоянные ссылки сбрасываются автоматически при изменении этой опции.', 'Enables the Markdown editor for posts and pages. Only HTML is stored in the post content field; Markdown is converted on save and not stored separately.' => 'Включает редактор Markdown для записей и страниц. В поле содержимого записи хранится только HTML; Markdown преобразуется при сохранении и не сохраняется отдельно.', 'Enter description.' => 'Введите описание.', 'Error' => 'Ошибка', 'Error:' => 'Ошибка:', 'Example: #div' => 'Пример: #div', 'Exclude CSS files' => 'Исключить файлы CSS', 'Exclude JavaScript files' => 'Исключить файлы JavaScript', 'Expands the At a Glance widget on the admin dashboard: shows all public post types, taxonomies, and the user count.' => 'Расширяет виджет «Прямо сейчас» на главной админки: показывает все публичныетипы записей, таксономии и число пользователей.', 'Extends the login cookie to 1 year when Remember Me is checked. Without the checkbox the default session length stays unchanged. Do not enable on shared computers.' => 'Продлевает cookie-сессию до 1 года, если при входе отмечено «Запомнитьменя». Без галочки срок остаётся стандартным. Не включайте на общихкомпьютерах.', 'Failed to delete files license.txt and readme.html from folder %s. Please delete them manually!' => 'Не удалось удалить файлы license.txt и readme.html из папки %s. Пожалуйста, удалите их вручную!', 'FAQ' => 'Часто задаваемые вопросы', 'Fetches the page that sent the pingback and requires a real link to this site in it. Same check as in Kama SpamBlock.' => 'Получает страницу, отправившую пингбэк, и требует наличия на ней реальной ссылки на этот сайт. Проверка та же, что и в Kama SpamBlock.', 'File' => 'Файл', 'Files license.txt and readme.html have been deleted from folder %s.' => 'Файлы license.txt и readme.html были удалены из папки %s.', 'Files to delete:' => 'Файлы для удаления:', 'Filter by role' => 'Фильтр по роли', 'filter...' => 'фильтр...', 'For one-button mode this is the accept button. For two-button mode this is the essential-only button.' => 'В режиме одной кнопки это кнопка подтверждения. В режиме двух кнопок это только основная кнопка.', 'Format: source,destination — one rule per line. Lines starting with #, // or ; are comments. Duplicate source URLs are overwritten.' => 'Формат: исходный-url,целевой-url — одно правило на строку. Строки с #, // или ; — комментарии. Дубликаты по исходному URL перезаписываются. Импорт — кнопками ниже.', 'Fully disables automatic and background updates for core, plugins, and themes. Use only on staging or when you control updates manually. When enabled, it also covers Tweaks "Block WordPress.org update HTTP requests" and "Disable aggressive update".' => 'Полностью отключает автоматические и фоновые обновления ядра, плагинов итем. Используйте только на staging или при ручном контроле обновлений. Привключении также перекрывает твики «Block WordPress.org update HTTP requests»и «Disable aggressive update».', 'General Settings' => 'Основные настройки', 'GitHub' => 'GitHub', 'Guid repair' => 'Ремонт Guid', 'Helps SVG files display correctly in the media library. Works together with setting 19 above, which allows SVG uploads.' => 'Помогает корректно показывать SVG-файлы в медиабиблиотеке. Работает вместе снастройкой 19 выше, которая разрешает загрузку SVG.', 'Hide adminbar in frontend for contributors, authors and subscribers' => 'Скрыть панель администратора в интерфейсе для участников, авторов и подписчиков', 'Hide languages in wp Front. Enter lang slug, separated: ", ".' => 'Скрыть языки в WP Front. Введите название языка, разделённое: ", ".', 'Hides Rank Math branding in admin and removes credit comments from the page source and XML sitemaps. Enabled by default; works only when Rank Math is active. Does not unlock Pro features.' => 'Скрывает фирменную символику Rank Math в административной панели и удаляет комментарии об авторстве из исходного кода страницы и XML-карт сайта. Включено по умолчанию; работает только при активном Rank Math. Не разблокирует функции Pro-версии.', 'Hides selected categories on the frontend: posts are excluded from archives and feeds, and a direct visit to a category archive redirects to the home page.' => 'Скрывает выбранные рубрики на сайте: записи не попадут в архивы и ленты, апрямой заход на архив рубрики перенаправит на главную.', 'Hides the admin bar on the frontend for authors, contributors, and subscribers. Editors and administrators still see it.' => 'Скрывает панель администратора на лицевой стороне сайта для авторов, участников и подписчиков. Редакторы и администраторы по-прежнему её видят.', 'Hides the Website field in the comment form. Reduces spam and avoids asking readers for extra data.' => 'Скрывает поле «Сайт» в форме комментария. Снижает спам и не просит лишнихданных у читателей.', 'Hides WordPress update notices from editors, authors, and other users without administrator rights.' => 'Скрывает уведомления об обновлении WordPress от редакторов, авторов и другихпользователей без прав администратора.', 'History is kept for %s months.' => 'История хранится в течение %s месяцев.', 'Hold every first comment for moderation' => 'Первый комментарий будет отправлен на модерацию.', 'Honeypot field' => 'Поле медовых ловушек', 'How long browsers may reuse a cached page. Cached files are also purged automatically whenever posts, terms, comments, menus, widgets or theme settings change. The recommended default is 3600 seconds.' => 'Как долго браузеры могут повторно использовать кэшированную страницу. Кэшированные файлы также автоматически очищаются при каждом изменении записей, терминов, комментариев, меню, виджетов или настроек темы. Рекомендуемое значение по умолчанию — 3600 секунд.', 'How redirects work' => 'Как работают редиректы', 'https://rwsite.ru' => 'https://rwsite.ru', 'If a user is logged into admin or personal account - show them fresh pages without cache. Otherwise, they may not see their changes or notifications.' => 'Если пользователь вошел в учетную запись администратора или личный кабинет, покажите ему свежие страницы без кэша. В противном случае он может не увидеть свои изменения или уведомления.', 'If an uploaded image has an empty alt attribute, uses the media library title. Helps with accessibility and SEO.' => 'Если у загруженного изображения пустой alt, подставляет заголовок файла измедиабиблиотеки. Помогает не забывать про доступность и SEO.', 'If posts have status "pending" show numbers it in menu' => 'Если сообщения имеют статус «ожидание», показывать их номера в меню.', 'Iframe (YouTube, Vimeo)' => 'Iframe (YouTube, Vimeo)', 'Images (img)' => 'Изображения (img)', 'Implement critical CSS' => 'Реализуйте критический CSS', 'Import failed. Try again.' => 'Ошибка импорта. Попробуйте ещё раз.', 'Import from file' => 'Импорт из файла', 'Import from text field' => 'Импорт из поля', 'Imported %1$d rule(s). Total in list: %2$d.' => 'Импортировано правил: %1$d. Всего в списке: %2$d.', 'Importing…' => 'Импорт…', 'In content' => 'В содержании', 'In two-button mode analytics code is loaded only after accepting all cookies.' => 'В режиме с двумя кнопками код аналитики загружается только после принятия всех файлов cookie.', 'Incorrect username or password.' => 'Неверное имя пользователя или пароль.', 'Install CodeStar Framework now' => 'Установите CodeStar Framework прямо сейчас!', 'Instance' => 'Пример', 'Instance Params' => 'Параметры экземпляра', 'IP' => 'IP', 'jQuery selector' => 'селектор jQuery', 'JS file handles separated by comma for exclusion from optimization. Examples: google-analytics, facebook-pixel, custom-scripts. WordPress system scripts (jQuery, etc.) are excluded automatically.' => 'Обработчики JS-файлов, разделенные запятой, исключают их из оптимизации. Примеры: google-analytics, facebook-pixel, custom-scripts. Системные скрипты WordPress (jQuery и т. д.) исключаются автоматически.', 'Kama SpamBlock is active and overlaps with this module. Its JavaScript nonce is not needed anymore and it can be deactivated.' => 'Модуль Kama SpamBlock активен и частично взаимодействует с этим модулем. Его JavaScript-код больше не нужен, и его можно отключить.', 'Keep selected taxonomy terms in place (disable checked on top)' => 'Оставьте выбранные термины таксономии на месте (отключите флажок вверху).', 'Keeps paragraph tags around shortcodes by disabling shortcode_unautop. Does not disable wpautop. Enable only if your layout requires these wrappers.' => 'Сохраняет теги абзацев вокруг шорткодов, отключая shortcode_unautop. Не отключает wpautop. Включайте только если такие обёртки нужны для вёрстки.', 'Keeps the latest 5 post revisions. Older revisions are removed when a new revision is saved. Autosaves are handled separately.' => 'Сохраняет последние 5 ревизий записи. Старые ревизии удаляются при сохранении новой ревизии. Автосохранения обрабатываются отдельно.', 'Keyboard shortcuts' => 'Клавиатурные сочетания', 'Last attempts' => 'Последние попытки', 'Lazy Loading' => 'Ленивая загрузка', 'Lazy loading of images and media files is a performance optimization technique where resources are loaded only when they come into the user\'s view. The module uses the modern Intersection Observer API with fallback for older browsers.<br><br><strong>Benefits:</strong><br>• Reduced page load time<br>• Traffic savings (especially on mobile devices)<br>• Improved Core Web Vitals (LCP, CLS)<br>• Automatic image compression with blur placeholder<br><br><strong>Support:</strong><br>• Images (img)<br>• Iframe (YouTube, Vimeo videos)<br>• Video elements<br>• Blur placeholder for smooth loading<br>• Fallback for IE11+' => 'Ленивая загрузка изображений и медиафайлов — это метод оптимизации производительности, при котором ресурсы загружаются только тогда, когда пользователь их видит. Модуль использует современный API Intersection Observer с возможностью отката для старых браузеров.<br><br><strong>Преимущества:</strong><br>• Сокращение времени загрузки страницы<br>• Экономия трафика (особенно на мобильных устройствах)<br>• Улучшение Core Web Vitals (LCP, CLS)<br>• Автоматическое сжатие изображений с использованием плейсхолдера размытия<br><br><strong>Поддержка:</strong><br>• Изображения (img)<br>• Iframe (видео YouTube, Vimeo)<br>• Видеоэлементы<br>• Размытие плейсхолдера для плавной загрузки<br>• Откат для IE11+', 'Leave this field empty' => 'Оставьте это поле пустым.', 'Link' => 'Связь', 'Link 1 text' => 'Текст ссылки 1', 'Link 1 URL' => 'Ссылка 1 URL', 'Link 2 text' => 'Текст ссылки 2', 'Link 2 URL' => 'Ссылка 2 URL', 'List of CSS file handles separated by comma that should not be optimized. Examples: critical-styles, admin-css, custom-admin-styles. WordPress system files are excluded automatically.' => 'Список дескрипторов CSS-файлов, разделённых запятыми, которые не следует оптимизировать. Примеры: critic-styles, admin-css, custom-admin-styles. Системные файлы WordPress автоматически исключаются.', 'List of Polylang language slugs to hide in the frontend switcher. Example: en, de. Spaces after commas are allowed.' => 'Список slug языков Polylang, которые нужно скрыть в переключателе на фронте.Пример: en, de. Пробелы после запятой допустимы.', 'Live preview' => 'Предварительный просмотр', 'Loading preview...' => 'Загрузка предварительного просмотра...', 'Loads a CSS framework into the TinyMCE preview and adds a button to insert framework markup. Needed when content uses grid and component classes.' => 'Подключает CSS-фреймворк в предпросмотр TinyMCE и кнопку вставки разметки.Нужен, если в контенте используются классы сетки и компонентов.', 'Loads jQuery from Google CDN instead of the WordPress bundled version. It may speed up loading but often breaks theme and plugin compatibility. Better to leave off by default.' => 'Подключает jQuery с CDN Google вместо версии WordPress. Может ускоритьзагрузку, но часто ломает совместимость с темой и плагинами. По умолчаниюлучше не включать.', 'Loads non-critical CSS files asynchronously after page rendering. Prevents render blocking, but may cause brief "flash of unstyled content" (FOUC).' => 'Асинхронно загружает некритичные CSS-файлы после рендеринга страницы. Предотвращает блокировку рендеринга, но может вызывать кратковременное «вспышку нестилизованного контента» (FOUC).', 'Loads the Open Sans font in the editor preview. Works independently of TinyMCE Advanced.' => 'Подключает шрифт Open Sans в предпросмотр редактора. Работает независимо отрасширенной панели TinyMCE Advanced.', 'Main switch for enabling/disabling cache. When ON: all site pages are saved to cache. When OFF: cache is not used, pages are generated each time anew.' => 'Основной переключатель для включения/выключения кэширования. В положении «ВКЛ.»: все страницы сайта сохраняются в кэше. В положении «ВЫКЛ.»: кэш не используется, страницы генерируются каждый раз заново.', 'Main switch of the module. Blocked comments are rejected before they reach the database: nothing is stored, no notification email is sent, and the page cache is not purged. Replaces the Kama SpamBlock plugin.' => 'Основной переключатель модуля. Заблокированные комментарии отклоняются до того, как попадут в базу данных: ничего не сохраняется, уведомление по электронной почте не отправляется, и кэш страницы не очищается. Заменяет плагин Kama SpamBlock.', 'Main switch of the module. When enabled, lazy loading is activated for selected media types. Recommended to enable on all sites for improved performance.' => 'Главный переключатель модуля. При включении активируется отложенная загрузка для выбранных типов медиа. Рекомендуется включить на всех сайтах для повышения производительности.', 'Main switch of the optimization module. When enabled, intelligent processing of all CSS and JavaScript resources on the site is activated. Recommended to enable on production sites for maximum performance.' => 'Главный переключатель модуля оптимизации. При включении активируется интеллектуальная обработка всех CSS и JavaScript-ресурсов на сайте. Рекомендуется включать на рабочих сайтах для максимальной производительности.', 'Maintenance' => 'Технические работы', 'Maintenance IP whitelist' => 'Белый список IP для режима техработ', 'Maintenance message' => 'Сообщение на странице техработ', 'Maintenance Mode' => 'Режим тех. работ', 'Maintenance role whitelist' => 'Белый список ролей для режима техработ', 'Markdown Editor' => 'Редактор Markdown', 'Max comments per day from one IP' => 'Максимальное количество комментариев в день с одного IP-адреса', 'Max comments per hour from one IP' => 'Максимальное количество комментариев в час с одного IP-адреса', 'Media Cleanup' => 'Очистка медиа', 'Media types for lazy loading' => 'Типы носителей для ленивой загрузки', 'Minify CSS files' => 'Минифицировать CSS-файлы', 'Minify JavaScript files' => 'Минифицировать файлы JavaScript', 'Minimum time on page (seconds)' => 'Минимальное время на странице (в секундах)', 'Moderation hold score' => 'Оценка модерации', 'No files to delete.' => 'Нет файлов для удаления.', 'No revisions found.' => 'Ревизии не найдены.', 'No spam comments blocked in the last 30 days.' => 'За последние 30 дней спам-комментарии не были заблокированы.', 'No valid rules found. Check the format: source,destination — one rule per line.' => 'Не найдено ни одного правила. Формат: исходный-url,целевой-url — одна строка = одно правило.', 'Noindex for search, attachment and date archives' => 'Noindex для поиска, вложений и архивов по дате', 'Not updated:' => 'Не обновлено:', 'Notice text' => 'Текст плашки', 'Off' => 'Выкл', 'Off to run html mode' => 'Выключите, чтобы запустить режим HTML', 'OK' => 'OK', 'On' => 'Вкл', 'Once Monthly' => 'Раз в месяц', 'One button (accept)' => 'Одна кнопка (принять)', 'One field per row: source,destination (comma, semicolon, or tab). Same format as CSV import.' => 'В каждой строке одно поле: источник, назначение (запятая, точка с запятой или табуляция). Формат такой же, как при импорте CSV.', 'One IP address per line. Whitelisted IPs can browse the site while maintenance mode is active.' => 'Один IP-адрес на строку. Адреса из белого списка могут просматривать сайт во время техработ.', 'One line = one rule. Delimiters: comma, semicolon, or tab. Lines starting with #, // or ; are comments. Use the import buttons below.' => 'Одна строка = одно правило. Разделители: запятая, точка с запятой или табуляция. Строки, начинающиеся с #, // или ;, являются комментариями. Используйте кнопки импорта ниже.', 'Opens an admin tool for bulk viewing and replacing GUID values. Change GUIDs deliberately — RSS subscribers may receive duplicate items.' => 'Открывает в админке инструмент массового просмотра и замены GUID. МеняйтеGUID только осознанно: подписчики RSS могут получить дубликаты материалов.', 'Or install the framework manually from GitHub' => 'Или установите фреймворк вручную из GitHub.', 'Page caching saves ready HTML and gzip files. Apache rules are installed automatically. For Nginx, include the generated wp-content/cache/pages/nginx.conf file inside the HTTPS server block and reload Nginx. Disable other full-page cache plugins to avoid conflicts.' => 'Кэширование страниц сохраняет готовые HTML-файлы и файлы gzip. Правила Apache устанавливаются автоматически. Для Nginx включите сгенерированный файл wp-content/cache/pages/nginx.conf в блок сервера HTTPS и перезагрузите Nginx. Отключите другие плагины полностраничного кэширования, чтобы избежать конфликтов.', 'Page generated' => 'Страница сгенерирована', 'Pages' => 'Страницы', 'Pages for auto-caching every hour. <strong>Leave empty for automatic mode:</strong> the home page + all pages from the main site menu (up to 10 pcs) will be loaded. Or specify manually: one URL per line, for example /about/, /services/' => 'Страницы для автоматического кэширования каждый час. <strong>Оставьте пустым для автоматического режима:</strong> будут загружены главная страница и все страницы главного меню сайта (до 10 шт.). Или укажите вручную: по одному URL на строку, например /about/, /services/', 'Pages that change frequently and should not be cached. One line - one URL. Examples: /wp-admin/ (admin), /checkout/ (checkout), /cart/ (cart), /my-account/ (personal account).' => 'Страницы, которые часто меняются и не должны кэшироваться. Одна строка — один URL. Примеры: /wp-admin/ (администрирование), /checkout/ (оформление заказа), /cart/ (корзина), /my-account/ (личный кабинет).', 'Paste Original Widget Class Name. See: https://codex.wordpress.org/Template_Tags/the_widget' => 'Вставьте исходное имя класса виджета. См.: https://codex.wordpress.org/Template_Tags/the_widget.', 'Paste rules into the field or choose a file.' => 'Вставьте правила в поле или выберите файл.', 'Paste the full counter HTML from Yandex Metrika or another service. The code is stored and injected as-is after consent. Leave empty to disable analytics loading.' => 'Вставьте полный HTML-код счетчика из Яндекс Метрики или другого сервиса. Код сохраняется и внедряется как есть после получения согласия. Оставьте поле пустым, чтобы отключить загрузку аналитики.', 'Performance, security, and admin enhancements for WordPress 6.6+: 48 WP Tweaker toggles, redirects, cookie banner, Markdown editor, plugin catalog, and comment spam protection.' => 'Улучшения производительности, безопасности и администрирования для WordPress 6.6+: 48 переключателей WP Tweaker, перенаправления, баннер cookie, редактор Markdown, каталог плагинов и защита от спама в комментариях.', 'Plugin list of ' => 'Список плагинов', 'Plugins list' => 'Список плагинов сайта', 'Polylang settings' => 'Настройки Polylang', 'Post or page ID' => 'ID записи или страницы', 'Post types' => 'Типы записей', 'Post types without comments' => 'Типы записей без комментариев', 'Posts' => 'Записи', 'Posts and Page Settings' => 'Настройки постов и страниц', 'Preload these pages' => 'Предварительно загрузить эти страницы', 'Preserve code and quotes in comments' => 'Сохраняйте код и кавычки в комментариях.', 'Prevents editing theme and plugin PHP files from the admin. Recommended for security: changes should go through git or FTP deliberately.' => 'Запрещает редактировать PHP-файлы тем и плагинов прямо из админки.Рекомендуется для безопасности: правки должны идти через git/FTP осознанно.', 'Prevents the site from sending pingbacks to itself. This is useless load and sometimes a source of spam.' => 'Запрещает сайту отправлять pingback самому себе. Это бесполезная нагрузка ииногда источник спама.', 'Prevents WordPress from installing a new default theme during a major core update. Convenient if you use only your own theme.' => 'Не устанавливать новую стандартную тему WordPress при крупном обновленииядра. Удобно, если вы используете только свою тему.', 'Preview Cleanup' => 'Очистка предварительного просмотра', 'Previous GUID: %s' => 'Предыдущий GUID: %s', 'Processing...' => 'Обработка...', 'Question' => 'Вопрос', 'Question for answer' => 'Вопрос для ответа', 'Rank Math: whitelabel / remove credits' => 'Rank Math: whitelabel / удалить авторские права', 'Read more ...' => 'Подробнее...', 'Reason' => 'Причина', 'Redirect rules' => 'Правила редиректов', 'Redirects' => 'Редиректы', 'Redirects author archive pages /author/name/ to the home page. Useful for a single-author blog. On a multi-author site it is better to leave this off.' => 'Перенаправляет страницы авторов /author/name/ на главную. Полезно для блогас одним автором. На мультиавторском сайте лучше выключить.', 'Registers the cleanup AJAX actions. Keep disabled until you are ready to review and remove generated image sizes.' => 'Регистрирует действия AJAX для очистки. Оставьте отключенным, пока не будете готовы просмотреть и удалить сгенерированные размеры изображений.', 'Rejected message' => 'Сообщение отклонено', 'Rejects a comment submitted faster than this value. The timestamp is written by JavaScript at page load, so the page cache does not break it. Set to 0 to disable.' => 'Отклоняет комментарий, отправленный быстрее указанного времени. Метка времени записывается JavaScript при загрузке страницы, поэтому кэш страницы её не нарушает. Установите значение 0, чтобы отключить.', 'Remove adjacent links to posts in the header' => 'Удалите смежные ссылки на посты в заголовке', 'Remove all revision' => 'Удалить все ревизии', 'Remove category base from URL' => 'Удалите базовый каталог категории из URL.', 'Remove Image' => 'Удалить изображение', 'Remove login-shake on errors' => 'Удалить логин-уведомления при ошибках', 'Remove post by email function' => 'Функция удаления сообщения по электронной почте', 'Remove REST and oEmbed discovery links from head' => 'Удалите ссылки REST и oEmbed из заголовка.', 'Remove RSD-Link' => 'Удалить RSD-ссылку', 'Remove shortlink in the header' => 'Удалить короткую ссылку в шапке', 'Remove site field in comment' => 'Удалить поле сайта в комментарии', 'Remove Windows Live Writer' => 'Удалить Windows Live Writer', 'Remove WP-Version in Header' => 'Удалить WP-версию в шапке', 'Removes /category/ from category URLs. Permalinks are flushed automatically when this option changes.' => 'Убирает /category/ из URL категорий. Постоянные ссылки сбрасываются автоматически при изменении этой опции.', 'Removes all default WordPress widgets from the available list. Dangerous on unfamiliar sites: you can lose already configured sidebar blocks.' => 'Удаляет все стандартные виджеты WordPress из списка доступных. Опасновключать на чужом сайте: можно потерять уже настроенные блоки в сайдбарах.', 'Removes from CSS files: comments, extra spaces, line breaks and tabs. Does not process files that are already minified or smaller than 1KB. Traffic savings: 15-30% per file.' => 'Удаляет из CSS-файлов комментарии, лишние пробелы, переносы строк и табуляции. Не обрабатывает файлы, которые уже минифицированы или размером меньше 1 КБ. Экономия трафика: 15–30% на файл.', 'Removes global-styles and classic-theme-styles on the frontend. It may speed up classic themes but can break blocks and typography. Check the site appearance after enabling.' => 'Убирает global-styles и classic-theme-styles на фронте. Может ускорить сайтна классических темах, но иногда ломает блоки и типографику. Проверяйтевнешний вид после включения.', 'Removes jquery-migrate on the frontend. It may speed up the site but can break older themes and plugins. Enable only after checking forms, sliders, and menus.' => 'Убирает jquery-migrate на фронте. Может ускорить сайт, но иногда ломаетстарые темы и плагины. Включайте только после проверки форм, слайдеров именю.', 'Removes link rel="prev/next" from the head. If the theme already outputs previous/next post navigation, this tag is redundant.' => 'Убирает link rel="prev/next" из <head>. Если тема сама выводит навигацию «предыдущая/следующая запись», этот тег избыточен.', 'Removes rel="nofollow" from comment author links. Enable only if you intentionally pass link equity from comments.' => 'Убирает rel="nofollow" у ссылок авторов комментариев. Включайте только если осознанно передаёте ссылочный вес из комментариев.', 'Removes REST API and oEmbed discovery links from the head. Visitors do not need them, and they reveal extra site structure.' => 'Убирает из <head> служебные ссылки на REST API и oEmbed. Посетителям они ненужны, зато лишняя информация о структуре сайта не светится.', 'Removes RSS feed links from the head. Enable only if you are sure RSS is not needed. For a blog it is usually better to leave this off so readers and aggregators can find your feed.' => 'Удаляет ссылки на RSS-ленту из заголовка. Включайте эту опцию только в том случае, если вы уверены, что RSS вам не нужен. Для блога обычно лучше оставить её отключенной, чтобы читатели и агрегаторы могли найти вашу ленту.', 'Removes the login form shake on wrong username or password. It does not affect site behavior — only the login page animation.' => 'Убирает «тряску» формы входа при ошибке логина/пароля. На работу сайта невлияет, просто делает страницу входа спокойнее.', 'Removes the RSD link for external editors. It is an extra technical tag in the head that is usually unused.' => 'Убирает RSD-ссылку для внешних редакторов. Это лишний технический тег в<head>, который обычно не используется.', 'Removes the shortlink — a short service URL for the page. It is not needed for SEO or visitors.' => 'Удаляет shortlink — короткую служебную ссылку на страницу. Для SEO ипользователей она не нужна.', 'Removes the wlwmanifest link from the head. It was only needed for the old Windows Live Writer app and is not required on modern sites.' => 'Удаляет служебную ссылку wlwmanifest из <head>. Она нужна только старойпрограмме Windows Live Writer и современным сайтам не требуется.', 'Removes the WordPress version number from page HTML and RSS. A small security measure: attackers have a harder time targeting a specific WP version.' => 'Убирает номер версии WordPress из HTML-кода страницы и RSS. Это небольшаямера безопасности: злоумышленнику сложнее подобрать эксплойт под конкретнуюверсию WP.', 'Repalse [...] to "Read more ..." for posts' => 'Заменить [...] на «Читать далее...» для сообщений', 'Replace all GUID values' => 'Заменить все GUID', 'Replace GUID values for all published posts?' => 'Заменить GUID у всех опубликованных записей?', 'Replaces the default [...] excerpt marker with a Read more... link.' => 'Заменяет стандартное [...] в анонсе записи на ссылку «Читать далее...».', 'Required for rules with *. Without this option only exact URL matches work, e.g. /old-page/ → /new-page/.' => 'Обязательно для правил с *. Без этой опции работают только точные совпадения, например /old-page/ → /new-page/.', 'Restores the classic TinyMCE editor instead of the block editor for all post types. On newer WordPress versions it may conflict with plugins built for blocks. For the widget screen only, use Shortcodes and Widgets → Disable Gutenberg for widgets.' => 'Возвращает классический редактор TinyMCE вместо блокового Gutenberg для всехтипов записей. На новых версиях WordPress может конфликтовать с плагинами,рассчитанными на блоки. Для экрана виджетов используйте Shortcodes andWidgets → Disable Gutenberg for widgets.', 'Restores the standard Custom Fields meta box on post edit screens. Needed when you work with meta fields without a separate plugin.' => 'Возвращает стандартный блок «Произвольные поля» на экранах редактированиязаписей. Нужен, если вы работаете с meta-полями без отдельного плагина.', 'Score' => 'Счет', 'Scoring threshold' => 'Пороговое значение для оценки', 'Select categories that should be hidden from archives, feeds, and direct category URLs. Legacy comma-separated IDs are still supported.' => 'Выберите категории, которые нужно скрыть из архивов, RSS и прямых URL категорий. Старый формат ID через запятую по-прежнему поддерживается.', 'Select element types for which lazy loading will be applied. Images are most effective for optimization.' => 'Выберите типы элементов, к которым будет применяться ленивая загрузка. Изображения наиболее эффективны для оптимизации.', 'Select post type' => 'Выбор post type', 'Select post types where comments should be disabled. If nothing is selected, comments are disabled everywhere.' => 'Выберите типы записей, где комментарии нужно отключить. Если ничего невыбрано — комментарии отключаются везде.', 'Selected roles can browse the site while maintenance mode is active. Administrators always have access.' => 'Выбранные роли могут просматривать сайт во время техработ. Администраторы всегда имеют доступ.', 'Sends every comment from a visitor without author cookies to the moderation queue, regardless of the score. The strongest protection against novel spam that no rule recognizes yet, at the cost of a manual approval for each new reader.' => 'Отправляет каждый комментарий от посетителя без авторских куки в очередь модерации, независимо от оценки. Самая надежная защита от нового спама, который пока не распознается ни одним правилом, ценой ручной проверки каждого нового читателя.', 'SEO Settings' => 'Настройки SEO', 'Server info' => 'ИНФОРМАЦИЯ О СЕРВЕРЕ', 'Set Alt in updload from Title media' => 'Установите Alt при обновлении загрузки с заголовка медиа-файла', 'Set limit post revisions to 5' => 'Установить ограничение на ревизий постов в 5', 'Shortcodes and Widgets' => 'Шорткоды и виджеты', 'Show additional shortcode?' => 'Показать дополнительный шорткод?', 'Show custom fields for categories and posts' => 'Показать custom fields для категорий и сообщений', 'Show posts IDs' => 'Показывать ID', 'Show posts thumbnails' => 'Показывать миниатюры записей', 'Showing message "Update wordpress" only admin' => 'Отображение сообщения "Обновить wordpress" только для администратора', 'Showing usages memory and time generate site page' => 'Отображение использования памяти и времени создания страницы сайта', 'Shown on the WordPress "Comment Submission Failure" page. Keep it friendly: bots ignore it, readers may see it by accident.' => 'Отображается на странице WordPress "Ошибка отправки комментария". Будьте вежливы: боты игнорируют это, читатели могут увидеть это случайно.', 'Shows a cookie consent banner on the frontend.' => 'Отображает на лицевой стороне сайта баннер с запросом согласия на использование файлов cookie.', 'Shows a full-width banner at the top of public pages. Useful during recovery, migration, or other temporary status.' => 'Показывает плашку на всю ширину вверху публичных страниц. Удобно при восстановлении, миграции или другом временном статусе.', 'Shows a generic Incorrect username or password message instead of hints like that user does not exist. This improves login page security.' => 'Показывает общее сообщение «Неверный логин или пароль» вместо подсказоквроде «такого пользователя не существует». Это повышает безопасностьстраницы входа.', 'Shows a hint with extra CF7 shortcodes: date, time, URL, IP, and user agent. Handy when collecting technical data from a form.' => 'Показывает подсказку с дополнительными шорткодами CF7: дата, время, URL, IPи user agent. Удобно при сборе технических данных из формы.', 'Shows a Pending count next to the Posts menu item in the admin.' => 'Показывает счётчик записей «На модерации» рядом с пунктом «Записи» в админ-меню.', 'Shows an "Under maintenance" page to all visitors except administrators. Useful when updating the theme, plugins, or migrating content.' => 'Показывает страницу «Технические работы» всем посетителям, кромеадминистраторов. Удобно при обновлении темы, плагинов или переносе контента.', 'Shows page generation time and memory usage in an HTML comment at the bottom of the page. Visible only to administrators. Better to leave off on production.' => 'Показывает в HTML-комментарии внизу страницы время генерации и расходпамяти. Видно только администратору. Для продакшена лучше выключить.', 'Shows server, domain, and WP_DEBUG information. Useful for diagnostics, but avoid enabling on shared hosting unless needed.' => 'Показывает техническую информацию о сервере, домене и режиме WP_DEBUG.Полезно для диагностики, но не включайте на shared-хостинге безнеобходимости.', 'Shows straight quotes and angle brackets in comments as readers typed them: disables typographic quotes on output and stores disallowed HTML tags as escaped text instead of stripping them. Core formatting tags (code, strong, links, and similar) still work. XSS protection is unchanged.' => 'В комментариях отображаются прямые кавычки и угловые скобки в том виде, в котором их ввели читатели: типографические кавычки в выводе отключены, а запрещенные HTML-теги сохраняются как экранированный текст вместо их удаления. Основные теги форматирования (code, strong, links и аналогичные) по-прежнему работают. Защита от XSS остается без изменений.', 'Shows the post thumbnail in the Posts admin table. Helps you quickly find posts with a featured image.' => 'Показывает миниатюру записи в таблице «Записи» в админке. Помогает быстронаходить материалы с обложкой.', 'Site status' => 'Статус сайта', 'Site status notice' => 'Плашка статуса сайта', 'Sliding window limit per IP address. Disabled by default: family and office IPs legitimately comment several times in a row. Set to 0 to keep it off.' => 'Ограничение на количество комментариев в скользящем окне для каждого IP-адреса. По умолчанию отключено: IP-адреса членов семьи и сотрудников офиса могут корректно оставлять комментарии несколько раз подряд. Установите значение 0, чтобы отключить эту функцию.', 'Sorry, the site is temporarily unavailable due to maintenance. Please try again later.' => 'Извините, сайт временно недоступен из-за технических работ. Пожалуйста, попробуйте зайти позже.', 'Specify date and time in format: 00.00.0000 00:00 or use the calendar' => 'Укажите дату и время в формате: 00.00.0000 00:00 или воспользуйтесь календарем', 'Start Cleanup' => 'Начать очистку', 'Stops URLs in comments from being turned into clickable links automatically. Useful against spam and unwanted outbound links in comments. Different from General Settings → Disable link Nofollow in comment, which only removes rel="nofollow".' => 'Не превращает URL в комментариях автоматически в кликабельные ссылки. Полезно против спама и лишних исходящих ссылок. Отличается от General Settings → Disable link Nofollow in comment, который только убирает rel="nofollow".', 'Tailwind CSS (future)' => 'Tailwind CSS (в будущем)', 'Text shown in the top banner. Leave empty to use the default message.' => 'Текст верхней плашки. Оставьте пустым, чтобы использовать сообщение по умолчанию.', 'The CodeStar Framework archive did not extract as expected.' => 'Архив CodeStar Framework не был распакован должным образом.', 'The CodeStar Framework could not be loaded after installation.' => 'После установки не удалось загрузить фреймворк CodeStar.', 'The CodeStar Framework entry file is missing after installation.' => 'После установки отсутствует входной файл CodeStar Framework.', 'The portion of the element that must enter the viewport to start loading. 0.1 = 10% of element visible. 1.0 = entire element visible.' => 'Часть элемента, которая должна попасть в область просмотра, чтобы началась загрузка. 0,1 = 10% видимого элемента. 1,0 = виден весь элемент.', 'The query returned no results.' => 'Запрос не вернул результатов.', 'The site is in recovery mode.' => 'Сайт находится в режиме восстановления.', 'This action replaces GUID values for all published public posts with their permalinks. RSS subscribers may receive duplicate items.' => 'Это действие заменит GUID у всех опубликованных публичных записей на их постоянные ссылки. Подписчики RSS могут получить дубликаты материалов.', 'This section allows you to clean up unused image sizes to free up disk space. WordPress generates multiple sizes for each uploaded image, but if your theme or plugins don\'t use all of them, they take up unnecessary space. Use this tool to identify and remove such files.<br><br><strong>When to use:</strong> After changing themes, disabling plugins that generate custom sizes, or optimizing site performance.<br><br><strong>Precautions:</strong> Always create a backup before cleanup. Use "Preview Cleanup" first to see what will be deleted. The tool preserves original images and "scaled" versions (up to 2000px). Deleted files cannot be recovered!' => 'Этот раздел позволяет очистить неиспользуемые размеры изображений, чтобы освободить место на диске. WordPress генерирует несколько размеров для каждого загруженного изображения, но если ваша тема или плагины не используют их все, они занимают лишнее место. Используйте этот инструмент для выявления и удаления таких файлов.<br><br><strong>Когда использовать:</strong> После смены темы, отключения плагинов, генерирующих нестандартные размеры, или оптимизации производительности сайта.<br><br><strong>Меры предосторожности:</strong> Всегда создавайте резервную копию перед очисткой. Сначала воспользуйтесь функцией «Предварительная очистка», чтобы увидеть, что будет удалено. Инструмент сохраняет исходные изображения и «масштабированные» версии (до 2000 пикселей). Удаленные файлы не подлежат восстановлению!', 'This will delete all image sizes except: %s. Files will be deleted permanently!' => 'Это приведет к удалению всех размеров изображений, кроме: %s. Файлы будут удалены безвозвратно!', 'Time' => 'Время', 'TinyMCE Settings' => 'Настройки TinyMCE', 'Top IPs' => 'Лучшие IP-адреса', 'Total size: %s MB' => 'Общий размер: %s МБ', 'Trailing slash in URLs' => 'Косая черта в конце URL-адресов', 'Transliterates Cyrillic to Latin for post, category, and filename slugs. Handy for Russian sites with Latin URLs.' => 'Переводит кириллицу в латиницу для slug записей, рубрик и имён файлов.Удобно для русскоязычных сайтов с латинскими URL.', 'Trims manual or automatic excerpts to about 180 characters with an ellipsis. Useful for post cards and SEO snippets.' => 'Обрезает ручную или автоматическую выдержку до ~180 символов с многоточием.Полезно для карточек записей и SEO-сниппетов.', 'Trust users who can moderate comments' => 'Доверяйте пользователям, которые могут модерировать комментарии.', 'Tweaks' => 'Твики', 'Two buttons (essential / accept all)' => 'Две кнопки (обязательная / принять все)', 'Uninstall' => 'Удалить', 'Uninstall error' => 'Ошибка при удалении', 'Uninstalling…' => 'Удаление…', 'Unknown error.' => 'Неизвестная ошибка.', 'Update all GUID' => 'Обновить все идентификаторы GUID', 'Update all GUID fields in the posts table with permalinks.' => 'Обновить все поля GUID в таблице posts постоянными ссылками.', 'Update error: %s' => 'Ошибка обновления: %s', 'Updated' => 'Обновлено', 'Updated:' => 'Обновлено:', 'Upload an .sql backup created by this module to restore it on this site.' => 'Загрузите резервную копию в формате .sql, созданную этим модулем, чтобы восстановить ее на этом сайте.', 'Upload backup' => 'Загрузить резервную копию', 'Upload backup file' => 'Загрузите файл резервной копии.', 'Upload failed.' => 'Загрузка не удалась.', 'Use scroll event listeners instead of Intersection Observer in browsers without IO API support. Slows performance but ensures compatibility.' => 'Используйте прослушиватели событий прокрутки вместо Intersection Observer в браузерах без поддержки API ввода-вывода. Снижает производительность, но обеспечивает совместимость.', 'Use wildcard redirects' => 'Подстановочные знаки (*) в редиректах', 'Use {link1} and {link2} placeholders for links configured below. A cookie icon is added automatically on the frontend.' => 'Используйте заполнители {link1} и {link2} для ссылок, настроенных ниже. Значок cookie автоматически добавляется на лицевой стороне сайта.', 'User avatar' => 'Аватар пользователя', 'Users role info' => 'Информация о ролях', 'Verify pingback and trackback sources' => 'Проверьте источники пингбэка и трекбэка.', 'Video elements' => 'Видеоэлементы', 'View all GUID' => 'Просмотреть все GUID', 'View all revisions stored in the posts table.' => 'Просмотреть все ревизии в таблице posts.', 'Viewport margin (rootMargin)' => 'Поле области просмотра (rootMargin)', 'Views' => 'Мнения', 'Visibility threshold' => 'Порог видимости', 'VK' => 'ВК', 'Welcome to ' => 'Добро пожаловать в', 'When disabled, redirect rules are saved but not applied on the site.' => 'Если выключено — правила сохраняются, но на сайте не применяются.', 'When saving a new post, writes its permalink into guid instead of a temporary ?p=ID URL. Useful for RSS and some integrations.' => 'При сохранении новой записи записывает в поле guid её постоянную ссылкувместо временного ?p=ID. Полезно для RSS и некоторых интеграций.', 'When you publish a new article or edit an old one - automatically delete all cache. So readers will immediately see fresh content. Disable if you publish often - this will slow down the site.' => 'При публикации новой статьи или редактировании старой — автоматически удаляйте весь кэш. Так читатели сразу увидят свежий контент. Отключите, если публикуете часто — это замедлит работу сайта.', 'Widget Name' => 'Имя виджета', 'Widget not found!' => 'Виджет не найден!', 'Wildcard * (not regex)' => 'Подстановочный знак * (не регулярное выражение)', 'With love by <span style="color: #ED4301;">A</span> Tikhomirov' => 'С любовью <span style="color: #ED4301;">A</span> Tikhomirov', 'Wordpress Addon' => 'Дополнения WP', 'WordPress download utilities are unavailable (wp-admin/includes/file.php could not be loaded).' => 'Утилиты для загрузки WordPress недоступны (не удалось загрузить файл wp-admin/includes/file.php).', 'WordPress tracking request blocked by wp-addon tweak.' => 'Запрос на отслеживание WordPress заблокирован твиком wp-addon.', 'WordPress.org update request blocked by wp-addon tweak.' => 'Запрос на обновление WordPress.org заблокирован твиком wp-addon.', 'Working…' => 'Работаю…', 'WP Addon uses the CodeStar Framework for its settings screen, but the framework was not found.' => 'Дополнение WP использует фреймворк CodeStar для экрана настроек, но фреймворк не был найден.', 'WP Addon: Comment Spam' => 'Дополнение для WordPress: Спам в комментариях', 'WP-Emojis deacivation' => 'Деактивация WP-Emojis', 'WPBakery Page Builder support ' => 'Поддержка конструктора страниц WPBakery', 'Write right link to guid for New posts.' => 'Напишите правильную ссылку на guid for New posts.', 'Yearly archive widget' => 'Виджет ежегодного архива', 'You are not allowed to install plugins.' => 'Установка плагинов запрещена.', 'You do not have permission to access this page.' => 'У вас нет прав для доступа к этой странице.', 'You do not have permission to activate or deactivate plugins.' => 'У вас нет разрешения на активацию или деактивацию плагинов.', 'You do not have permission to delete plugins.' => 'У вас нет разрешения на удаление плагинов.', 'You do not have permission to import redirect rules.' => 'Недостаточно прав для импорта редиректов.', 'You do not have permission to install plugins.' => 'У вас нет разрешения на установку плагинов.', 'You must be logged in to access the REST API.' => 'Для доступа к REST API необходимо войти в систему.', '⚠️ Allow download types file: SVG, DOC, djv ..' => '⚠️ Разрешены файлы следующих типов для скачивания: SVG, DOC, djv и др.', '⚠️ Block WordPress.org update HTTP requests' => '⚠️ Блокировка HTTP-запросов на обновление WordPress.org', '⚠️ Disable agressive update' => '⚠️ Отключить агрессивное обновление', '⚠️ Disable all updates.' => '⚠️ Отключите все обновления.', '⚠️ Disable guttenber?' => '⚠️ Отключить Guttenber?', '⚠️ Disable heartbeat on frontend (slow down in admin)' => '⚠️ Отключите проверку активности на внешнем интерфейсе (это замедлит работу в админке).', '⚠️ Disable REST API for unauthorized users' => '⚠️ Отключите REST API для неавторизованных пользователей', '⚠️ Disable shortcode_unautop (keep paragraph tags around shortcodes)' => '⚠️ Отключите shortcode_unatop (сохраняйте теги абзацев вокруг шорткодов)', '⚠️ Disable site indexing.' => '⚠️ Отключите индексацию сайта.', '⚠️ Don`t allow to show specific categories in frontend.' => '⚠️ Не разрешайте отображение определенных категорий на лицевой стороне сайта.', '⚠️ Extend login session to 1 year when "Remember Me" is checked' => '⚠️ При включенной опции "Запомнить меня" срок действия сеанса входа в систему может быть увеличен до 1 года.', '⚠️ Get jquery from google cloud' => '⚠️ Получите jQuery из Google Cloud', '⚠️ Redirect author archives to home page' => '⚠️ Перенаправить архив автора на главную страницу', '⚠️ Remove global theme styles on frontend' => '⚠️ Удалите глобальные стили темы на фронтенде', '⚠️ Remove jQuery Migrate' => '⚠️ Удалить jQuery Migrate', '⚠️ Remove RSS links' => '⚠️ Удалите RSS-ссылки', '⚠️ Remove Standard WP widget' => '⚠️ Удалить стандартный виджет WordPress', '⚠️ This option enable interface for replace wp guide to right GUID.' => '⚠️ Эта опция включает интерфейс для замены GUID в WordPress на правильный.']];
